        int n = edges.Length + 1;
        var g = new List<int>[n];
        for (int i = 0; i < n; i++) {
            g[i] = new List<int>();
        }
        foreach (var e in edges) {
            int a = e[0], b = e[1];
            g[a].Add(b);
            g[b].Add(a);
        }
        return g;
    }

    private void Dfs(List<int>[] g, int[] c, int[] cnt) {
        var stk = new Stack<int[]>();
        stk.Push(new int[] { 0, -1, 0 });
