            int[] cur = stk.Pop();
            int a = cur[0], fa = cur[1], d = cur[2];
            c[a] = d;
            cnt[d]++;
            foreach (var b in g[a]) {
                if (b != fa) {
                    stk.Push(new int[] { b, a, d ^ 1 });
                }
            }
        }
    }
}

